INSERT INTO `v2_content` VALUES (446,'lv','<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"><span>SIA \"TVIDS\"</span></span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"><span>Reģistrācijas numurs 40003416115<br /></span></span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"><span><span>PVN maksātāja numurs&nbsp;<span>LV40003416115</span></span></span></span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"><span>Rīga, Vaidelotes iela 20 - 21, LV-1055</span></span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">29536065, 29558938</span></span></p>',239,2),(447,'ru','<p><span style=\"font-family: \'comic sans ms\', sans-serif; font-size: medium;\">ООО \"TVIDS\"&nbsp;</span></p>\n<p><span style=\"font-family: \'comic sans ms\', sans-serif; font-size: medium;\">Регистрационный номер 40003416115</span></p>\n<p><span style=\"font-family: \'comic sans ms\', sans-serif; font-size: medium;\">Номер налогоплательщика&nbsp;<span>LV40003416115</span></span></p>\n<p><span style=\"font-family: \'comic sans ms\', sans-serif; font-size: medium;\">Рига, улица Вайделотес 20 - 21, LV-1055</span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">29536065, 29558938</span></span></p>',239,2),(448,'en','<p>Контакты</p>',239,2),(434,'lv','<p>&nbsp;&nbsp; <span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">Pie mums jūs varat iegūt gatavus gultas veļas kompektus vai pasūtīt gultas veļas &scaron;ū&scaron;anu pec jūsu izmēriem. Mūsu produkcija būs lieliskā dāvana gan sev, gan radiniekiem, vai darba kolleģim. Jūs netiksiet pievilti.</span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"><br />&nbsp; Mūsu websaitā ir pieiejami sekojo&scaron;ie izstrādājumi.<br />&nbsp; </span></span><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">Izstrādājumi no bjaza</span></span><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"> :</span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">&nbsp;&nbsp;&nbsp;&nbsp; - <a href=\"http://www.tvids.lv/index.php/lv/web/show/275\">dažādu izmēru izstrādājumi<br /></a></span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">&nbsp;&nbsp;&nbsp;&nbsp; - </span></span><a href=\"http://www.tvids.lv/index.php/lv/web/show/469\"><span style=\"font-family: comic sans ms,sans-serif;\"><span style=\"font-size: medium;\">citi izstrādājumi<br /></span></span></a></p>\n<p><span style=\"font-family: comic sans ms,sans-serif;\"><span style=\"font-size: medium;\"><br /></span></span></p>\n<p><span style=\"font-family: comic sans ms,sans-serif; font-size: medium;\">&nbsp; </span><span style=\"font-size: medium;\"></span><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">Izstrādājumi no satīna</span></span><span style=\"font-family: comic sans ms,sans-serif; font-size: medium;\"> :</span></p>\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">- <a href=\"http://www.tvids.lv/index.php/lv/web/show/297\">dažādu izmēru komplekti<br /></a></span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"><br /></span></span></p>\n<p><span style=\"font-family: comic sans ms,sans-serif; font-size: medium;\">&nbsp; </span><span style=\"font-size: medium;\"></span><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">Izstrādājumi no </span></span><span style=\"font-family: comic sans ms,sans-serif; font-size: medium;\">flaneļa :</span></p>\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">- <a href=\"http://www.tvids.lv/index.php/lv/web/show/274\">halati</a></span></span></p>\n<p>&nbsp;</p>\n<p><span style=\"font-family: comic sans ms,sans-serif; font-size: medium;\">&nbsp; Bez tam mēs varam izpildīt &scaron;uvē&scaron;anas specpasūtījumus</span><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"> par nelielām un saprātīgām cenām.<br /></span></span></p>',235,2),(435,'ru','<p>&nbsp;&nbsp; <span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">У нас вы можете приобрести готовое постельное белье или сделать индивидуальный заказ по вашим размерам. Уверены - наша продукция вам понравится. Все постельное белье имеет красивые рисунки и будет прекрасным подарком и себе, и родственникам, и коллегам.<br /><br />&nbsp; В данный момент на сайте размещены следующие изделия.<br />&nbsp; Изделия из бязи :</span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">&nbsp;&nbsp;&nbsp;&nbsp; - <a href=\"http://www.tvids.lv/index.php/ru/web/show/275\">комплекты различных размеров</a></span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">&nbsp;&nbsp;&nbsp;&nbsp; - </span></span><a href=\"http://www.tvids.lv/index.php/ru/web/show/469\"><span style=\"font-family: comic sans ms,sans-serif;\"><span style=\"font-size: medium;\">прочие изделия</span></span></a></p>\n<p><span style=\"font-family: comic sans ms,sans-serif;\"><span style=\"font-size: medium;\"><br /></span></span></p>\n<p><span style=\"font-family: comic sans ms,sans-serif; font-size: medium;\">&nbsp; Изделия из сатина :</span></p>\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">- <a href=\"http://www.tvids.lv/index.php/ru/web/show/297\">комплекты различных размеров</a></span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"><br /></span></span></p>\n<p><span style=\"font-family: comic sans ms,sans-serif; font-size: medium;\">&nbsp; Изделия из фланели :</span></p>\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">- <a href=\"http://www.tvids.lv/index.php/ru/web/show/274\">халаты</a></span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\"><br /></span></span></p>\n<p><span style=\"font-family: comic sans ms,sans-serif; font-size: medium;\">&nbsp;&nbsp; Кроме того </span><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">мы можем осуществить пошив по спецзаказу по небольшим и приемлемым ценам.</span></span></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>',235,2),(436,'en','<p>Начало</p>',235,2),(443,'lv','<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">&nbsp;&nbsp; Sia \"TVIDS\" dibināta 1998.g. Mūsu specializācija - gultas veļas ražo&scaron;ana un pārdo&scaron;ana.<br /><br />&nbsp;&nbsp; Mēs esam ieintereseti jaunajos partneros, kā arī vienmēr esam gatavi sadarboties. Visus jautājumus un piedāvājumus lūdzu sūtīt uz emailu tvids(at)inbox.lv</span></span></p>',238,2),(444,'ru','<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">&nbsp;&nbsp; Sia \"TVIDS\" основана в 1998 г. и специализируется на пошиве и продаже постельного белья из бязей и сатинов, а также на выполнении индивидуальных заказов по пошиву изделий из нетяжелых тканей.<br />&nbsp;&nbsp; </span></span></p>\n<p><span style=\"font-size: medium;\"><span style=\"font-family: comic sans ms,sans-serif;\">&nbsp;&nbsp; Мы заинтересованы в поиске партнеров и всегда готовы к сотрудничеству. Все вопросы и предложения просим присылать на имайл tvids(at)inbox.lv</span></span><span style=\"font-family: \'comic sans ms\', sans-serif; font-size: small;\">&nbsp; &nbsp;</span></p>',238,2),(445,'en','<p>О нас</p>',238,2),(541,'ru','Пододеяльник 145x210,<br> простыня 140x210,<br> 2 нав. (50x60 или 60x60)',284,1),(540,'lv','Pārvalks 145x210,<br> palags 140x210,<br> 2 spilvendr. (50x60 vai 60x60)',284,1),(548,'lv','Pārvalks 145x210x2,<br> palags 220x210,<br> 2 spilvendr. (50x60 vai 60x60)',288,1),(549,'ru','Пододеяльник 145x210x2,<br> простыня 220x210,<br> 2 нав. (50х60 или 60х60)',288,1),(891,'ru','Комплект:<br> пододеяльник 145х210,<br> 2 нав. (50x60 или 60x60)',438,1),(890,'lv','Komplekts:<br> pārvalks 145x210,<br> 2 spilvendr. (50x60 vai 60x60)',438,1),(506,'lv','Email забыли пароль',269,1),(507,'ru','Email забыли пароль',269,1),(508,'en','Email забыли пароль',269,1),(509,'lv','<p>Sveicināti!</p>\n<p>&nbsp;Jūs gribat izmainīt savu paroli web lapā www.tvids.lv?<br />&nbsp;link: \\\\(link_forgot)\\\\</p>\n<p>&nbsp;Ar cieņu.</p>\n<p>tvids.lv komanda</p>',269,2),(510,'ru','<p>Sveicināti!</p>\n<p>&nbsp;Jūs gribat izmainīt savu paroli web lapā www.tvids.lv?<br />&nbsp;link: \\\\(link_forgot)\\\\</p>\n<p>&nbsp;Ar cieņu.</p>\n<p>tvids.lv komanda</p>',269,2),(511,'en','<p>Sveicināti!</p>\n<p>&nbsp;Jūs gribat izmainīt savu paroli web lapā www.woodygoody.lv?<br />&nbsp;link: \\\\(link_forgot)\\\\</p>\n<p>&nbsp;Ar cieņu.</p>\n<p>woodygoody.lv komanda</p>',269,2),(364,'en','Contacts',239,1),(363,'ru','Контакты',239,1),(362,'lv','Kontakti',239,1),(361,'en','About us',238,1),(360,'ru','О нас',238,1),(359,'lv','Par mums',238,1),(523,'ru','Бязь - Комплекты',275,1),(522,'lv','Bjazj - Komplekti',275,1),(512,'lv','Bjaz',270,1),(513,'ru','Бязь',270,1),(350,'lv','Sākums',235,1),(351,'ru','Начало',235,1),(352,'en','Home',235,1),(569,'ru','Сатин - Комплекты',297,1),(568,'lv','Satīns - Komplekti',297,1),(452,'lv','Email заказ',253,1),(453,'ru','Email заказ',253,1),(454,'en'